function incoherence_index(n, F):
    if F is empty: return 0
    dist = array of size n initialized to +inf
    # first layer: one atom from start residue 0
    queue = empty FIFO
    for a in F:
        r = a mod n
        if dist[r] > 1: dist[r] = 1; push r onto queue
    while queue not empty:
        r = pop queue
        if r == 0: return dist[0]          # shortest loop closed
        for a in F:
            r2 = (r + a) mod n
            if dist[r2] > dist[r] + 1:
                dist[r2] = dist[r] + 1; push r2 onto queue
    return dist[0] if dist[0] < +inf else 0

